  "basic": "'use client';\n\nimport React from 'react';\nimport { Avatar, List } from '@ceebee/ui/client';\n\nconst data = [\n  {\n    title: 'Ceebee UI Title 1',\n  },\n  {\n    title: 'Ceebee UI Title 2',\n  },\n  {\n    title: 'Ceebee UI Title 3',\n  },\n  {\n    title: 'Ceebee UI Title 4',\n  },\n];\n\nconst App: React.FC = () => (\n  <List\n    itemLayout=\"horizontal\"\n    dataSource={data}\n    renderItem={(item, index) => (\n      <List.Item>\n        <List.Item.Meta\n          avatar={<Avatar src={`https://api.dicebear.com/10.x/lorelei/svg?seed=${index}`} />}\n          title={<a href=\"https://ceebee.dev\">{item.title}</a>}\n          description=\"Ceebee UI, a design language for background applications, is refined by the Ceebee team\"\n        />\n      </List.Item>\n    )}\n  />\n);\n\nexport default App;\n",
  "drag-sorting-handler": "'use client';\n\nimport React, { createContext, useContext, useMemo, useState } from 'react';\nimport { HolderOutlined } from '@ant-design/icons';\nimport type { DragEndEvent, DraggableAttributes } from '@dnd-kit/core';\nimport { DndContext } from '@dnd-kit/core';\nimport type { SyntheticListenerMap } from '@dnd-kit/core/dist/hooks/utilities';\nimport { restrictToVerticalAxis } from '@dnd-kit/modifiers';\nimport {\n  arrayMove,\n  SortableContext,\n  useSortable,\n  verticalListSortingStrategy,\n} from '@dnd-kit/sortable';\nimport { CSS } from '@dnd-kit/utilities';\nimport { Button, List } from '@ceebee/ui/client';\nimport type { GetProps } from '@ceebee/ui/client';\n\ninterface SortableListItemContextProps {\n  setActivatorNodeRef?: (element: HTMLElement | null) => void;\n  listeners?: SyntheticListenerMap;\n  attributes?: DraggableAttributes;\n}\n\nconst SortableListItemContext = createContext<SortableListItemContextProps>({});\n\nconst DragHandle: React.FC = () => {\n  const { setActivatorNodeRef, listeners, attributes } = useContext(SortableListItemContext);\n  return (\n    <Button\n      type=\"text\"\n      size=\"small\"\n      icon={<HolderOutlined />}\n      style={{ cursor: 'move' }}\n      ref={setActivatorNodeRef}\n      {...attributes}\n      {...listeners}\n    />\n  );\n};\n\nconst SortableListItem: React.FC<GetProps<typeof List.Item> & { itemKey: number }> = (props) => {\n  const { itemKey, style, ...rest } = props;\n\n  const {\n    attributes,\n    listeners,\n    setNodeRef,\n    setActivatorNodeRef,\n    transform,\n    transition,\n    isDragging,\n  } = useSortable({ id: itemKey });\n\n  const listStyle: React.CSSProperties = {\n    ...style,\n    transform: CSS.Translate.toString(transform),\n    transition,\n    ...(isDragging ? { position: 'relative', zIndex: 9999 } : {}),\n  };\n\n  const memoizedValue = useMemo<SortableListItemContextProps>(\n    () => ({ setActivatorNodeRef, listeners, attributes }),\n    [setActivatorNodeRef, listeners, attributes],\n  );\n\n  return (\n    <SortableListItemContext.Provider value={memoizedValue}>\n      <List.Item {...rest} ref={setNodeRef} style={listStyle} />\n    </SortableListItemContext.Provider>\n  );\n};\n\nconst App: React.FC = () => {\n  const [data, setData] = useState([\n    { key: 1, content: 'Racing car sprays burning fuel into crowd.' },\n    { key: 2, content: 'Japanese princess to wed commoner.' },\n    { key: 3, content: 'Australian walks 100km after outback crash.' },\n    { key: 4, content: 'Man charged over missing wedding girl.' },\n    { key: 5, content: 'Los Angeles battles huge wildfires.' },\n  ]);\n\n  const onDragEnd = ({ active, over }: DragEndEvent) => {\n    if (!active || !over) {\n      return;\n    }\n    if (active.id !== over.id) {\n      setData((prevState) => {\n        const activeIndex = prevState.findIndex((i) => i.key === active.id);\n        const overIndex = prevState.findIndex((i) => i.key === over.id);\n        return arrayMove(prevState, activeIndex, overIndex);\n      });\n    }\n  };\n\n  return (\n    <DndContext\n      modifiers={[restrictToVerticalAxis]}\n      onDragEnd={onDragEnd}\n      id=\"list-drag-sorting-handler\"\n    >\n      <SortableContext items={data.map((item) => item.key)} strategy={verticalListSortingStrategy}>\n        <List\n          dataSource={data}\n          renderItem={(item) => (\n            <SortableListItem key={item.key} itemKey={item.key}>\n              <DragHandle /> {item.key} {item.content}\n            </SortableListItem>\n          )}\n        />\n      </SortableContext>\n    </DndContext>\n  );\n};\n\nexport default App;\n",
  "drag-sorting": "'use client';\n\nimport React, { useState } from 'react';\nimport type { DragEndEvent } from '@dnd-kit/core';\nimport { DndContext, PointerSensor, useSensor, useSensors } from '@dnd-kit/core';\nimport { restrictToVerticalAxis } from '@dnd-kit/modifiers';\nimport {\n  arrayMove,\n  SortableContext,\n  useSortable,\n  verticalListSortingStrategy,\n} from '@dnd-kit/sortable';\nimport { CSS } from '@dnd-kit/utilities';\nimport { List } from '@ceebee/ui/client';\nimport type { GetProps } from '@ceebee/ui/client';\n\nconst SortableListItem: React.FC<GetProps<typeof List.Item> & { itemKey: number }> = (props) => {\n  const { itemKey, style, children, ...rest } = props;\n\n  const { attributes, listeners, setNodeRef, transform, transition, isDragging } = useSortable({\n    id: itemKey,\n  });\n\n  const listStyle: React.CSSProperties = {\n    ...style,\n    transform: CSS.Translate.toString(transform),\n    transition,\n    cursor: 'move',\n    ...(isDragging ? { position: 'relative', zIndex: 9999 } : {}),\n  };\n\n  return (\n    <List.Item {...rest} ref={setNodeRef} style={listStyle}>\n      <div {...attributes} {...listeners}>\n        {children}\n      </div>\n    </List.Item>\n  );\n};\n\nconst App: React.FC = () => {\n  const [data, setData] = useState([\n    { key: 1, content: 'Racing car sprays burning fuel into crowd.' },\n    { key: 2, content: 'Japanese princess to wed commoner.' },\n    { key: 3, content: 'Australian walks 100km after outback crash.' },\n    { key: 4, content: 'Man charged over missing wedding girl.' },\n    { key: 5, content: 'Los Angeles battles huge wildfires.' },\n  ]);\n\n  const sensors = useSensors(\n    useSensor(PointerSensor, {\n      activationConstraint: {\n        // https://docs.dndkit.com/api-documentation/sensors/pointer#activation-constraints\n        distance: 1,\n      },\n    }),\n  );\n\n  const onDragEnd = ({ active, over }: DragEndEvent) => {\n    if (!active || !over) {\n      return;\n    }\n    if (active.id !== over.id) {\n      setData((prev) => {\n        const activeIndex = prev.findIndex((i) => i.key === active.id);\n        const overIndex = prev.findIndex((i) => i.key === over.id);\n        return arrayMove(prev, activeIndex, overIndex);\n      });\n    }\n  };\n\n  return (\n    <DndContext\n      sensors={sensors}\n      modifiers={[restrictToVerticalAxis]}\n      onDragEnd={onDragEnd}\n      id=\"list-drag-sorting\"\n    >\n      <SortableContext items={data.map((item) => item.key)} strategy={verticalListSortingStrategy}>\n        <List\n          dataSource={data}\n          renderItem={(item) => (\n            <SortableListItem key={item.key} itemKey={item.key}>\n              {item.key} {item.content}\n            </SortableListItem>\n          )}\n        />\n      </SortableContext>\n    </DndContext>\n  );\n};\n\nexport default App;\n",
